function adminConfigFormStart(array $state,string $section):void{ ?>
<form method="post" data-inline-editor><?php csrfField()?><input type="hidden" name="action" value="config_save_draft"><input type="hidden" name="draft_version" value="<?=$state['draft_version']?>"><input type="hidden" name="config_section" value="<?=h($section)?>">
<?php }
function adminConfigFormEnd():void{ ?><div class="form-actions"><button>保存草稿</button><span class="muted">发布后应用到 App</span></div></form><?php }
?>
