<div class="setting-list"><?php foreach(['ai_enabled'=>['Club AI','允许用户发送消息和使用 AI 分析。'],'ai_native_home'=>['新版首页','启用 V2 原生首页，关闭即回退旧首页。'],'club_enabled'=>['俱乐部活动','在 App 中开放成长季与奖励。'],'action_system_enabled'=>['AI 业务操作','允许 AI 提供记录、计划调整等操作。'],'ai_context_references_v1'=>['引用记录','在聊天中引用训练、饮食和身体记录。'],'ai_streaming_v2'=>['实时显示回复','边生成边显示聊天回复。']] as $key=>[$label,$hint]):?><label class="setting-row"><span><strong><?=h($label)?></strong><small><?=h($hint)?></small></span><input type="checkbox" role="switch" name="<?=h($key)?>" <?=$draft[$key]?'checked':''?>></label><?php endforeach?></div>
<details class="advanced-settings"><summary>高级运行设置</summary><div class="setting-list"><?php foreach(['ai_fast_intent_v1'=>'常用指令快速处理','ai_router_v3'=>'按任务智能选择模型','training_commands'=>'训练实时提交','direct_records'=>'饮食与体重实时提交'] as $key=>$label):?><label class="setting-row"><span><?=h($label)?></span><input type="checkbox" role="switch" name="<?=h($key)?>" <?=$draft[$key]?'checked':''?>></label><?php endforeach?></div><p class="muted">影响提交方式和模型调度，调整前请核对实际运行情况。</p></details>
<?php adminConfigFormEnd();?></section>
<?php elseif($pagePanel==='onboarding'): $content=$draft['onboarding_content']; ?>
<section class="card"><h2>新用户体验</h2><?php adminConfigFormStart($state,'onboarding');?><div class="setting-list"><?php foreach(['onboarding_v2_enabled'=>'启用新用户引导','contextual_tips_enabled'=>'显示首次操作提示'] as $key=>$label):?><label class="setting-row"><span><?=h($label)?></span><input type="checkbox" role="switch" name="<?=$key?>" <?=$draft[$key]?'checked':''?>></label><?php endforeach?></div><label>每人每日引导 AI 次数<input type="number" name="onboarding_assist_daily_limit" min="1" max="100" value="<?=$draft['onboarding_assist_daily_limit']?>" required></label><?php adminConfigFormEnd();?></section>
<section class="card"><div class="section-head"><div><h2>欢迎语</h2><p class="muted"><?=h(trim($content['welcome_title'].' '.$content['welcome_body'])?:'尚未设置欢迎语')?></p></div><?php adminEditorStart('welcome-content','修改欢迎语','修改');adminConfigFormStart($state,'onboarding-welcome');?><label>标题<input name="onboarding_welcome_title" maxlength="40" value="<?=h($content['welcome_title'])?>"></label><label>一句话说明<textarea name="onboarding_welcome_body" maxlength="300" rows="3"><?=h($content['welcome_body'])?></textarea></label><?php adminConfigFormEnd();adminEditorEnd();?></div></section>
<section class="card"><div class="section-head"><div><h2>快捷入口文案</h2><p class="muted"><?=h(implode(' · ',array_filter($content['task_labels']))?:'尚未设置入口文案')?></p></div><?php adminEditorStart('onboarding-actions','修改快捷入口','修改');adminConfigFormStart($state,'onboarding-actions');foreach(['plan_create'=>'安排训练','plan_import'=>'整理已有计划','meal_log'=>'记录饮食','workout_log'=>'记录训练','explore'=>'了解 App'] as $key=>$label):?><label><?=h($label)?><input name="onboarding_task_<?=$key?>" maxlength="12" value="<?=h($content['task_labels'][$key]??'')?>"></label><?php endforeach;adminConfigFormEnd();adminEditorEnd();?></div></section>
<section class="card"><div class="section-head"><div><h2>首次操作提示</h2><p class="muted">在对应功能首次使用时显示，可由用户关闭。</p></div><?php adminEditorStart('onboarding-tips','修改操作提示','修改');adminConfigFormStart($state,'onboarding-tips');$tips=$content['tips']?:array_map(fn($id)=>['id'=>$id,'screen'=>$id,'title'=>'','body'=>''],['first_set','food_fraction','report','task_center']);foreach($tips as $index=>$tip):?><fieldset><legend><?=h(['first_set'=>'训练登记','food_fraction'=>'饮食份量','report'=>'分析报告','task_center'=>'任务进度'][$tip['id']]??'操作提示')?></legend><input type="hidden" name="onboarding_tips[<?=$index?>][id]" value="<?=h($tip['id'])?>"><input type="hidden" name="onboarding_tips[<?=$index?>][screen]" value="<?=h($tip['screen'])?>"><label>标题<input name="onboarding_tips[<?=$index?>][title]" maxlength="30" value="<?=h($tip['title'])?>"></label><label>说明<input name="onboarding_tips[<?=$index?>][body]" maxlength="120" value="<?=h($tip['body'])?>"></label></fieldset><?php endforeach;adminConfigFormEnd();adminEditorEnd();?></div></section>
<?php elseif($pagePanel==='announcement'): ?>
<section class="card narrow"><h2>App 公告</h2><?php adminConfigFormStart($state,'announcement');?><label class="setting-row"><span>显示公告</span><input type="checkbox" role="switch" name="announcement_enabled" <?=$draft['announcement']['enabled']?'checked':''?>></label><label>标题<input name="announcement_title" maxlength="80" value="<?=h($draft['announcement']['title'])?>"></label><label>正文<textarea name="announcement_body" maxlength="600" rows="5"><?=h($draft['announcement']['body'])?></textarea></label><?php adminConfigFormEnd();?></section>
<?php elseif($pagePanel==='versions'): ?>
<section class="card narrow"><h2>版本更新提示</h2><?php adminConfigFormStart($state,'versions');?><label>提示更新的最低构建号<input type="number" name="minimum_build" min="0" max="1000000" value="<?=$draft['minimum_build']?>" required><small>低于此版本会看到更新提示，填 0 关闭。</small></label><label>最新构建号<input type="number" name="latest_build" min="0" max="1000000" value="<?=$draft['latest_build']?>" required></label><?php adminConfigFormEnd();?></section>
<?php else:$historyPage=max(1,(int)($_GET['page']??1));$versions=query('SELECT v.*,a.username FROM app_config_versions v LEFT JOIN admin_accounts a ON a.id=v.admin_id ORDER BY v.id DESC LIMIT 21 OFFSET '.(($historyPage-1)*20))->fetchAll();$more=count($versions)>20;$versions=array_slice($versions,0,20);?>
<section class="card"><h2>发布记录</h2><div class="table-wrap"><table><thead><tr><th>版本</th><th>操作</th><th>说明</th><th>操作人 / 时间</th><th></th></tr></thead><tbody><?php foreach($versions as $v):?><tr><td>v<?=(int)$v['version']?></td><td><?=h(['draft'=>'保存草稿','publish'=>'发布','rollback'=>'恢复'][$v['action']]??$v['action'])?></td><td><?=h($v['note']?:'—')?></td><td><?=h($v['username']??'系统')?><small><?=h(stamp($v['created_at']))?></small></td><td><form method="post" data-confirm="将此版本恢复为草稿？核对并发布后才会应用到 App。"><?php csrfField()?><input type="hidden" name="action" value="config_rollback"><input type="hidden" name="draft_version" value="<?=$state['draft_version']?>"><input type="hidden" name="version_id" value="<?=(int)$v['id']?>"><button class="quiet">恢复为草稿</button></form></td></tr><?php endforeach;if(!$versions):?><tr><td colspan="5" class="empty">暂无发布记录</td></tr><?php endif?></tbody></table></div><?php adminPageCount($historyPage,$more);?></section>
<?php endif ?>
